@layer components {
  :where([data-control-family="timeline"][data-slot="root"]) {
    --timeline-indicator-background: var(--background);
    --timeline-indicator-foreground: var(--muted-foreground);
    --timeline-running-foreground: var(--primary-text);
    --timeline-success-foreground: var(--foreground);
    --timeline-error-foreground: var(--destructive-text);
    --timeline-separator-background: var(--border);
    --timeline-title-foreground: var(--foreground);
  }
  :where([data-control-family="timeline"][data-slot="indicator"]) {
    border-radius: 9999px;
    background: var(--timeline-indicator-background);
    color: var(--timeline-indicator-foreground);
  }

  :where(
    [data-control-family="timeline"][data-slot="item"][data-state="running"]
      [data-control-family="timeline"][data-slot="indicator"]
  ) {
    color: var(--timeline-running-foreground);
  }

  :where(
    [data-control-family="timeline"][data-slot="item"][data-state="success"]
      [data-control-family="timeline"][data-slot="indicator"]
  ) {
    color: var(--timeline-success-foreground);
  }

  :where(
    [data-control-family="timeline"][data-slot="item"][data-state="error"]
      [data-control-family="timeline"][data-slot="indicator"]
  ) {
    color: var(--timeline-error-foreground);
  }

  :where([data-control-family="timeline"][data-slot="separator"]) {
    background: var(--timeline-separator-background);
  }

  :where([data-control-family="timeline"][data-slot="title"]) {
    color: var(--timeline-title-foreground);
    font-size: var(--text-label);
  }

  :where([data-control-family="timeline"][data-slot="description"]) {
    color: var(--muted-foreground);
    font-size: var(--text-label);
  }

  :where([data-control-family="timeline"][data-slot="description"]) {
    line-height: calc(var(--spacing) * 5);
  }

  :where([data-control-family="timeline"][data-slot="title"]) {
    font-weight: var(--font-weight-medium);
    line-height: calc(var(--spacing) * 5);
  }
}

@property --timeline-indicator-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --timeline-indicator-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --timeline-running-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --timeline-success-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --timeline-error-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --timeline-separator-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

@property --timeline-title-foreground {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

import type {
  TimelineContentProps,
  TimelineDescriptionProps,
  TimelineIndicatorProps,
  TimelineItemProps,
  TimelineMetaProps,
  TimelineProps,
  TimelineSeparatorProps,
  TimelineTitleProps,
} from "@/components/control-ui/contracts";
import { cn } from "@/components/control-ui/lib/cn";

export function Timeline({ className, ...props }: TimelineProps) {
  return (
    <ol data-control-ui="timeline" data-control-family="timeline" data-slot="root" {...props} className={cn("grid min-w-0", className)} />
  );
}

export function TimelineItem({ state = "neutral", className, ...props }: TimelineItemProps) {
  return (
    <li
      data-control-ui="timeline"
      data-control-family="timeline"
      data-slot="item"
      data-state={state}
      {...props}
      className={cn("group/timeline-item relative grid min-w-0 grid-cols-[1rem_minmax(0,1fr)] gap-x-3 pb-5 last:pb-0", className)}
    />
  );
}

export function TimelineIndicator({ className, ...props }: TimelineIndicatorProps) {
  return (
    <span
      aria-hidden="true"
      data-control-ui="timeline"
      data-control-family="timeline"
      data-slot="indicator"
      {...props}
      className={cn("relative z-10 col-start-1 row-start-1 flex size-4 shrink-0 items-center justify-center", className)}
    />
  );
}

export function TimelineSeparator({ className, ...props }: TimelineSeparatorProps) {
  return (
    <span
      aria-hidden="true"
      data-control-ui="timeline"
      data-control-family="timeline"
      data-slot="separator"
      {...props}
      className={cn("absolute top-5 bottom-0 left-[calc(0.5rem-0.5px)] col-start-1 w-px group-last/timeline-item:hidden", className)}
    />
  );
}

export function TimelineContent({ className, ...props }: TimelineContentProps) {
  return (
    <div
      data-control-ui="timeline"
      data-control-family="timeline"
      data-slot="content"
      {...props}
      className={cn("col-start-2 row-start-1 grid min-w-0 gap-1", className)}
    />
  );
}

export function TimelineTitle({ className, ...props }: TimelineTitleProps) {
  return (
    <div data-control-ui="timeline" data-control-family="timeline" data-slot="title" {...props} className={cn("min-w-0", className)} />
  );
}

export function TimelineDescription({ className, ...props }: TimelineDescriptionProps) {
  return (
    <div
      data-control-ui="timeline"
      data-control-family="timeline"
      data-slot="description"
      {...props}
      className={cn("min-w-0 wrap-anywhere", className)}
    />
  );
}

export function TimelineMeta({ className, ...props }: TimelineMetaProps) {
  return (
    <div
      data-control-ui="timeline"
      data-control-family="timeline"
      data-slot="meta"
      {...props}
      className={cn("mt-1 flex min-w-0 flex-wrap items-center gap-1.5", className)}
    />
  );
}
